const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const hongKong = ee.Geometry.Rectangle([113.82, 22.12, 114.52, 22.56]); // Bounding box for Hong Kong

  const dateRange1_start = '2020-02-10';
  const dateRange1_end = '2020-02-25';

  const dateRange2_start = '2020-04-20';
  const dateRange2_end = '2020-05-12';

  const NO2_BAND = 'tropospheric_NO2_column_number_density';
  const QA_BAND = 'qa_value';
  const QA_THRESHOLD = 0.75; // Recommended QA value threshold for Sentinel-5P NO2

  // Function to process NO2 data for a given period
  const getNO2Data = (startDate, endDate, geometry, periodName) => {
    let collection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
      .filterDate(startDate, endDate)
      .filterBounds(geometry)
      .select([NO2_BAND, QA_BAND]);

    // Check if the collection is empty
    if (collection.size().getInfo() === 0) {
      console.log(`No images found for ${periodName} (${startDate} to ${endDate}).`);
      return { mean: null, pixels: 0, cloud_pct: 100, status: 'C1' };
    }

    // Apply QA mask
    collection = collection.map(image => image.updateMask(image.select(QA_BAND).gt(QA_THRESHOLD)));

    // Calculate mean NO2 for the period
    const meanImage = collection.mean();

    // Check if meanImage is null or empty after masking
    if (meanImage === null) {
      console.log(`Mean image is null for ${periodName} after QA masking.`);
      return { mean: null, pixels: 0, cloud_pct: 100, status: 'C2' }; // Indicates no valid pixels
    }

    // Calculate the mean NO2 value and pixel count over the geometry
    const result = meanImage.reduceRegion({
      reducer: ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: geometry,
      scale: 1000, // Use a reasonable scale to avoid memory issues
      maxPixels: 1e9
    });

    const meanNO2 = result.get(NO2_BAND).getInfo();
    const pixelCount = result.get(NO2_BAND + '_count').getInfo();

    if (pixelCount === 0) {
      console.log(`No valid pixels found for ${periodName} after QA masking.`);
      return { mean: null, pixels: 0, cloud_pct: 100, status: 'C2' };
    }

    return { mean: meanNO2, pixels: pixelCount, status: 'OK' };
  };

  // 2. Data Acquisition & Check for Period 1
  const data1 = getNO2Data(dateRange1_start, dateRange1_end, hongKong, 'Period 1 (Feb 2020)');
  if (data1.status !== 'OK') {
    console.log(`<answer>${data1.status}</answer>`);
    return;
  }
  console.log(`Feb 2020 NO2 Mean: ${data1.mean !== null ? data1.mean.toFixed(6) : 'N/A'}, Pixels: ${data1.pixels}`);

  // 3. Data Acquisition & Check for Period 2
  const data2 = getNO2Data(dateRange2_start, dateRange2_end, hongKong, 'Period 2 (Apr-May 2020)');
  if (data2.status !== 'OK') {
    console.log(`<answer>${data2.status}</answer>`);
    return;
  }
  console.log(`Apr-May 2020 NO2 Mean: ${data2.mean !== null ? data2.mean.toFixed(6) : 'N/A'}, Pixels: ${data2.pixels}`);

  // 4. Validation & Final Answer
  if (data1.mean === null || data2.mean === null) {
    console.log("One or both mean NO2 values are null after calculation.");
    console.log("<answer>C3</answer>");
    return;
  }

  // Multiply by 1e6 to make the numbers more readable (original unit is mol/m^2)
  const meanNO2_period1_scaled = data1.mean * 1e6;
  const meanNO2_period2_scaled = data2.mean * 1e6;

  console.log(`Feb 2020 Scaled NO2 Mean: ${meanNO2_period1_scaled.toFixed(3)} (x10^-6 mol/m^2)`);
  console.log(`Apr-May 2020 Scaled NO2 Mean: ${meanNO2_period2_scaled.toFixed(3)} (x10^-6 mol/m^2)`);

  if (meanNO2_period2_scaled > meanNO2_period1_scaled) {
    console.log("<answer>A</answer>"); // Yes, NO2 levels increased
  } else {
    console.log("<answer>B</answer>"); // No, NO2 levels did not increase
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
